_sr('select_multiple q7_17_opts','q7_17','Q7.17 ‡ What were the reasons for not reporting the incident or seeking help? (Multiple answers; do not read list.)','Q7.17 ‡ ঘটনাটি না জানানো বা সাহায্য না চাওয়ার কারণগুলো কী ছিল? (একাধিক উত্তর; তালিকাটি পড়ে শোনাবেন না।)', relevant="${q7_14}='2'"),
_sr('text','q7_17_other','Other (specify)','অন্যান্য (উল্লেখ করুন)', relevant="${q7_14}='2' and selected(${q7_17},'10')"),
_sr('select_one q7_18_opts','q7_18','Q7.18 Ask everyone: Do you know where to report a case of violence affecting someone in your community?','Q7.18 সবাইকে জিজ্ঞাসা করুন: আপনার জনগোষ্ঠীর কেউ সহিংসতার শিকার হলে, কোথায় ঘটনাটি জানানো যায় তা কি আপনি জানেন?'),
_sr('select_multiple q7_19_opts','q7_19','Q7.19 Where? (Multiple answers; do not read list.)','Q7.19 কোথায়? (একাধিক উত্তর; তালিকাটি পড়ে শোনাবেন না।)', relevant="not(${q7_18}='2' or ${q7_18}='3')"),
